import { test, expect } from '@playwright/test';

test.describe('Search Suggestions Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should highlight matching part of search term in suggestions', async ({ page }) => {
    // Set up API interception for search suggestions
    await page.route('**/api/search-suggestions', (route) => {
      route.continue();
    });

    // Set up API interception for search results
    await page.route('**/api/search-results', (route) => {
      route.continue();
    });

    // Set up API interception for search API
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Type a search term with partial match
    const searchInput = page.getByPlaceholder('Search...');
    await searchInput.fill('playwright');

    // Wait for suggestions to appear
    const suggestionsList = page.getByRole('listbox');
    await expect(suggestionsList).toBeVisible();

    // Verify suggestions are displayed
    const suggestionItems = page.locator('[data-testid="suggestion-item"]');
    await expect(suggestionItems).toHaveCount(3);

    // Verify the first suggestion is highlighted
    const firstSuggestion = page.getByText('Playwright Test Script');
    await expect(firstSuggestion).toBeVisible();
    await expect(firstSuggestion).toHaveAttribute('data-highlight', 'playwright');

    // Verify the second suggestion is highlighted
    const secondSuggestion = page.getByText('Playwright Playwright');
    await expect(secondSuggestion).toBeVisible();
    await expect(secondSuggestion).toHaveAttribute('data-highlight', 'playwright');

    // Verify the third suggestion is highlighted
    const thirdSuggestion = page.getByText('Playwright Playwright Playwright');
    await expect(thirdSuggestion).toBeVisible();
    await expect(thirdSuggestion).toHaveAttribute('data-highlight', 'playwright');

    // Verify the search input has the correct value
    const searchInputValue = page.getByLabel('Search');
    await expect(searchInputValue).toHaveValue('playwright');

    // Verify the search results are displayed
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();

    // Verify the first result is highlighted
    const firstResult = page.getByText('Playwright Test Script');
    await expect(firstResult).toBeVisible();
    await expect(firstResult).toHaveAttribute('data-highlight', 'playwright');

    // Verify the second result is highlighted
    const secondResult = page.getByText('Playwright Playwright');
    await expect(secondResult).toBeVisible();
    await expect(secondResult).toHaveAttribute('data-highlight', 'playwright');

    // Verify the third result is highlighted
    const thirdResult = page.getByText('Playwright Playwright Playwright');
    await expect(thirdResult).toBeVisible();
    await expect(thirdResult).toHaveAttribute('data-highlight', 'playwright');

    // Verify the search results list is visible
    await expect(searchResults).toBeVisible();
  });

